const triggerEvents = `-- name: TriggerEvents :many
SELECT id, event_order, event_type, decision, resource FROM audit_events
WHERE event_order > ? AND substr(event_type, 1, 5) <> 'sync.'
ORDER BY CAST(event_order AS TEXT) LIMIT ?
`

type TriggerEventsParams struct {
	EventOrder int64
	Limit      int64
}

type TriggerEventsRow struct {
	ID         string
	EventOrder int64
	EventType  string
	Decision   string
	Resource   sql.NullString
}

// scanSyncTriggers: the events after the cursor, delivery's own excluded,
// ordered and limited as the TypeScript query orders them: by event_order
// as text (its ORDER BY names the output column, event_order::text), a
// defect kept for parity (CONVERGE.md).
func (q *Queries) TriggerEvents(ctx context.Context, arg TriggerEventsParams) ([]TriggerEventsRow, error) {
	rows, err := q.db.QueryContext(ctx, triggerEvents, arg.EventOrder, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TriggerEventsRow
	for rows.Next() {
		var i TriggerEventsRow
		if err := rows.Scan(
			&i.ID,
			&i.EventOrder,
			&i.EventType,
			&i.Decision,
			&i.Resource,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateTarget = `-- name: UpdateTarget :exec
UPDATE sync_targets
SET connection_id = ?1, destination = ?2, canonical_destination = ?3,
    mapping = ?4, remove_orphans = ?5, redeploy = ?6, needs_sync = 1,
    next_attempt_at = NULL, version = version + 1, updated_at = ?7,
    last_notes = CASE WHEN CAST(?8 AS INTEGER) <> 0 THEN NULL ELSE last_notes END,
    last_drift_at = CASE WHEN CAST(?8 AS INTEGER) <> 0 THEN NULL ELSE last_drift_at END,
    last_drift_count = CASE WHEN CAST(?8 AS INTEGER) <> 0 THEN NULL ELSE last_drift_count END,
    last_drift_names = CASE WHEN CAST(?8 AS INTEGER) <> 0 THEN NULL ELSE last_drift_names END,
    last_drift_event_id = CASE WHEN CAST(?8 AS INTEGER) <> 0 THEN NULL ELSE last_drift_event_id END,
    redeploy_paid = CASE WHEN CAST(?8 AS INTEGER) <> 0 OR NOT ?6 THEN redeploy_owed ELSE redeploy_paid END
WHERE id = ?9
`

type UpdateTargetParams struct {
	ConnectionID  string
	Destination   string
	Canonical     string
	Mapping       string
	RemoveOrphans bool
	Redeploy      bool
	At            sql.NullInt64
	Changed       int64
	ID            string
}

// updateTarget: queued for a converge; a destination change takes the
// notes and drift observed at the old one, and settles an owed redeploy
// (as does turning redeploys off).
func (q *Queries) UpdateTarget(ctx context.Context, arg UpdateTargetParams) error {
	_, err := q.db.ExecContext(ctx, updateTarget,
		arg.ConnectionID,
		arg.Destination,
		arg.Canonical,
		arg.Mapping,
		arg.RemoveOrphans,
		arg.Redeploy,
		arg.At,
		arg.Changed,
		arg.ID,
	)
	return err
}

const upsertIntegration = `-- name: UpsertIntegration :exec
INSERT INTO member_integrations (organization_id, identity_id, kind, resource_id, changes, first_at, last_at)
VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?6)
ON CONFLICT (organization_id, identity_id, kind, resource_id) DO UPDATE SET
  changes = (SELECT json_group_array(value) FROM (
    SELECT DISTINCT value FROM (
      SELECT value FROM json_each(member_integrations.changes) UNION ALL SELECT value FROM json_each(excluded.changes))
    ORDER BY value)),
  first_at = min(member_integrations.first_at, excluded.first_at),
  last_at = max(member_integrations.last_at, excluded.last_at)
`

type UpsertIntegrationParams struct {
	OrganizationID string
	IdentityID     string
	Kind           string
	ResourceID     string
	Changes        string
	At             int64
}

// indexIntegrations, one row: changes (a sorted set, given sorted) is
// the sorted union, and the times only widen.
func (q *Queries) UpsertIntegration(ctx context.Context, arg UpsertIntegrationParams) error {
	_, err := q.db.ExecContext(ctx, upsertIntegration,
		arg.OrganizationID,
		arg.IdentityID,
		arg.Kind,
		arg.ResourceID,
		arg.Changes,
		arg.At,
	)
	return err
}

